// Groovy's wardrobe items, drawn in code (round 5 item 3, round 3E item 7):
// the shapes of docs/design/wardrobe-v2/Wardrobe.dc.html and Seasonal.dc.html
// (art/wardrobe.ts, art/seasonal.ts, generated by scripts/gen-art.py), in the
// boards' coordinates mapped onto his body (art/draw.ts), plus the Diamond
// crown, his six-month reward, drawn in the same style.
//
// Coordinates are BotEngine's body space: origin at the body centre, y down,
// R = W × 0.3, rx = 1.14 R, ry = 0.88 R. Items sit on named anchors taken from
// his live pillow outline (headAnchors, round 3H item 1; placed the way
// Coucou's items sit on its head, none of its art):
// - face items are mapped onto his real eyes (BotEngine.eyeCentres), so the
//   board's lenses land on them at any angle and narrow as the eyes do; the
//   arms of glasses run back to the sides of his head, behind him;
// - hats sit on the rim, an ellipse on his head whose ends lie on his outline
//   and whose height follows his nod; the far half of the rim is behind him;
// - neck items sit on the collar, the same kind of ellipse near his base,
//   its back half behind him;
// - the pool ring goes round his middle and only slides.
// Nothing is clipped to the body, so nothing is cut off at the edge. Hats
// drop on, glasses slide down into place and neck items pop in.

import { Ease } from "../core/anim";
import { drawShapes, type Art, type Shape } from "./art/draw";
import { SEASONAL_ART } from "./art/seasonal";
import { WARDROBE_ART } from "./art/wardrobe";
import { SLOT_OF } from "./appearance";
import type { Accessory, Outfit } from "./wardrobe";
import { PILLOW_BOW, halfWidthAt, pillowXY } from "./pillow";

type Ctx = CanvasRenderingContext2D;

/** Head geometry + the spring lag of the soft parts (−1…1, in head units). */
export interface Head {
  R: number;
  rx: number;
  ry: number;
  yaw: number;
  pitch: number;
  physDx: number;
  physDy: number;
  /** Pendulum angle of dangling parts (the engine's spring), 0 at rest. */
  swing?: number;
  /** His eyes in body space, left then right (the engine's); face items sit on them. */
  eyes?: [[number, number], [number, number]];
}

export function makeHead(R: number, yaw = 0, pitch = 0, physDx = 0, physDy = 0): Head {
  return { R, rx: R * 1.14, ry: R * 0.88, yaw, pitch, physDx, physDy };
}

/** An ellipse on his body: centre, half width (on his outline), half height. */
export interface Ring { cx: number; cy: number; a: number; b: number }

/** Named anchors taken from his live pillow outline (round 3H item 1), body space. */
export interface Anchors {
  /** The top of his head (the pillow's dipped crown). */
  crown: [number, number];
  /** Where a hat's rim meets his head; its ends lie on his outline. */
  rim: Ring;
  rimLeft: [number, number];
  rimRight: [number, number];
  rimTop: [number, number];
  eyeL: [number, number];
  eyeR: [number, number];
  eyeLine: number;
  /** Where a neck item goes round him, near the base; its ends lie on his outline. */
  collar: Ring;
  neck: [number, number];
  /** The bottom of his body. */
  base: number;
}

/** His outline's exponent (skins.ts SHAPE); the minis never wear items. */
const BODY_EXP = 3.0;
/** The rim's and the collar's height on him, as a fraction of ry. */
/** Where a hat's rim sits on his head (round 3M item 2: down on the crown, not on top of it). */
export const RIM_V = -0.5;
/** Where the boards' hats have their rim: the art's seat line. */
const ART_RIM_V = -0.72;
export const COLLAR_V = 0.8;

/**
 * Round 3M item 1, his head as a fake 3D body, drawn in 2D: an ellipsoid whose
 * rings follow his real outline (half width `a` from the pillow at that height,
 * depth DEPTH × a), turned by the same yaw and pitch his eyes use. Every anchor
 * is a point on it; `z > 0` means facing the viewer, so a wrapping part has a
 * front piece (after the body) and a back piece (before it, hidden by it).
 */
const DEPTH = 0.8;
/** The camera looks down on him a little, so a ring shows as an ellipse. */
const VIEW = 0.2;

export interface P3 { x: number; y: number; z: number }

/** The angle that tips a ring's front down on screen: the camera's tilt less his nod up. */
export function ringTilt(H: Head): number {
  return VIEW - H.pitch;
}

/** A point `t` radians round the ring centred at body height `yc` (0 = the front, ±π/2 = his sides). */
export function ringPoint(H: Head, yc: number, a: number, t: number, depth = DEPTH): P3 {
  const c = depth * a;
  const X = a * Math.sin(t);
  const Z = c * Math.cos(t);
  const cy = Math.cos(H.yaw);
  const sy = Math.sin(H.yaw);
  // His outline does not narrow when he turns, so the turned ring is scaled to keep its sides on it.
  const k = a / Math.hypot(a * cy, c * sy);
  const x1 = (X * cy + Z * sy) * k;
  const z1 = -X * sy + Z * cy;
  const phi = ringTilt(H);
  return { x: x1, y: yc + z1 * Math.sin(phi), z: z1 * Math.cos(phi) - yc * Math.sin(phi) };
}

/** A ring's outline, `n` points all the way round, starting at the front. */
export function ringPoints(H: Head, yc: number, a: number, n = 40, depth = DEPTH): P3[] {
  const out: P3[] = [];
  for (let i = 0; i <= n; i++) out.push(ringPoint(H, yc, a, (i / n) * Math.PI * 2, depth));
  return out;
}

/** The pieces of a closed ring facing the viewer (`front`) or turned away: each a run of points. */
export function splitRing(pts: P3[], front: boolean): P3[][] {
  const runs: P3[][] = [];
  let cur: P3[] = [];
  for (const q of pts) {
    if (q.z >= 0 === front) cur.push(q);
    else if (cur.length) {
      runs.push(cur);
      cur = [];
    }
  }
  if (cur.length) runs.push(cur);
  // The ring starts at the front: a front run that wraps past the end joins the first.
  if (runs.length > 1 && pts[0].z >= 0 === front && pts[pts.length - 1].z >= 0 === front) {
    const last = runs.pop() as P3[];
    runs[0] = last.concat(runs[0]);
  }
  return runs;
}

/** The ring at a fraction `v` of ry (negative = up): its centre, half width and wobble included. */
function ringAt(H: Head, v: number): { yc: number; a: number } {
  const yc = v * H.ry + H.physDy * H.ry * 0.05;
  return { yc, a: halfWidthAt(yc, H.rx, H.ry, BODY_EXP) };
}

/** His neck line: low on him, and always a gap of at least 0.12 ry below his eyes. */
function neckY(H: Head): number {
  const eyeBottom = H.eyes ? Math.max(H.eyes[0][1], H.eyes[1][1]) : H.ry * 0.1;
  return Math.min(H.ry * 0.9, Math.max(COLLAR_V * H.ry, eyeBottom + 0.22 * H.ry));
}

export function headAnchors(H: Head): Anchors {
  const { rx, ry } = H;
  const wx = H.physDx * rx * 0.05;
  const phi = ringTilt(H);
  const lift = -Math.sin(H.pitch) * ry * 0.12;
  const r0 = ringAt(H, RIM_V);
  const rim = { cx: wx, cy: r0.yc, a: r0.a, b: Math.max(0.5, DEPTH * r0.a * Math.abs(Math.sin(phi))) };
  const colY = neckY(H) + H.physDy * ry * 0.05;
  const ca = halfWidthAt(colY, rx, ry, BODY_EXP);
  const collar = { cx: wx, cy: colY, a: ca, b: Math.max(0.5, DEPTH * ca * Math.abs(Math.sin(phi))) };
  const sx = rx / 36;
  const sy = ry / 31;
  const [eyeL, eyeR] = H.eyes ?? [[-12 * sx, sy], [12 * sx, sy]];
  return {
    crown: [wx, -ry * (1 - PILLOW_BOW) + lift + H.physDy * ry * 0.05],
    rim,
    rimLeft: [rim.cx - rim.a, rim.cy],
    rimRight: [rim.cx + rim.a, rim.cy],
    rimTop: [rim.cx, rim.cy - rim.b],
    eyeL,
    eyeR,
    eyeLine: (eyeL[1] + eyeR[1]) / 2,
    collar,
    neck: [collar.cx, collar.cy],
    base: ry * (1 - PILLOW_BOW),
  };
}

/** The board's own Groovy shows through on the seasonal cards: the glints in his eyes. */
function boardEye(s: Shape): boolean {
  return s.f?.toUpperCase() === "#FFFFFF" && /^M(36|60) 61A2 1\.3/.test(s.d);
}

/** The six-month reward: a gold crown with a single pale-blue diamond. */
const DIAMOND_CROWN: Art = {
  front: [
    { d: "M30 33L29 19L38 25L44 12L50 21L56 12L62 25L71 19L70 33Z", f: "#E0B84A", s: "#B8902A", w: 0.8 },
    { d: "M30 29H70V33H30Z", f: "#C99A2E" },
    { d: "M36 31A1.2 1.2 0 1 0 38.4 31A1.2 1.2 0 1 0 36 31ZM61.6 31A1.2 1.2 0 1 0 64 31A1.2 1.2 0 1 0 61.6 31Z", f: "#FFE08A" },
    { d: "M42.8 12A1.4 1.4 0 1 0 45.6 12A1.4 1.4 0 1 0 42.8 12ZM54.4 12A1.4 1.4 0 1 0 57.2 12A1.4 1.4 0 1 0 54.4 12Z", f: "#FFE08A" },
    { d: "M27.8 19A1.3 1.3 0 1 0 30.4 19A1.3 1.3 0 1 0 27.8 19ZM69.6 19A1.3 1.3 0 1 0 72.2 19A1.3 1.3 0 1 0 69.6 19Z", f: "#FFE08A" },
    { d: "M50 19L55 25L50 31L45 25Z", f: "#CFF3FF", s: "#7FD4FF", w: 0.6 },
    { d: "M45 25H55M50 19V31", s: "#FFFFFF", w: 0.4, o: 0.7 },
    { d: "M47.5 22.5L49 21", s: "#FFFFFF", w: 0.7, cap: 1 },
  ],
};

/** The board's flat glasses arms (out to the card's edge): his run back behind his head. */
const BOARD_ARM = /M\d+(?:\.\d+)? \d+(?:\.\d+)?H(?:14|86)/g;

/** Shapes drawn from the head model instead (round 3M item 3): straps, bands and the arms of glasses. */
const PROCEDURAL: Partial<Record<string, number[]>> = { piratePatch: [0], pilotGoggles: [0], headphones: [0, 1], bunnyEarBand: [2], batWingBand: [2] };

function clean(art: Art, id = ""): Art {
  const armed = ["roundSpecs", "shades", "heartGlasses"].includes(id);
  const drop = PROCEDURAL[id] ?? [];
  const keep = (list?: Shape[]) =>
    list?.filter((s, i) => !boardEye(s) && !(list === art.front && drop.includes(i))).map((s) => (armed && !s.f ? { ...s, d: s.d.replace(BOARD_ARM, "").trim() } : s));
  return { behind: keep(art.behind), body: keep(art.body), front: keep(art.front) };
}

/** Every item's art. The cards' eye colours are the board's, not the item's: left out. */
const ITEM_ART: Record<string, Art> = Object.fromEntries([
  ...Object.entries(WARDROBE_ART).map(([id, a]) => [id, clean(a, id)]),
  ...Object.entries(SEASONAL_ART).map(([id, a]) => [id, clean(a)]),
  ["diamondCrown", DIAMOND_CROWN],
]);

/** An item's shapes (tests). */
export function itemArt(item: Accessory): Art | undefined {
  return ITEM_ART[item];
}

// ── Layers and transitions ────────────────────────────────────────────────────

let scratch: HTMLCanvasElement | null = null;

/**
 * Draws `fn` at `alpha` as one layer, so overlapping parts don't show through
 * each other while an item fades.
 */
function withLayer(ctx: Ctx, alpha: number, fn: (c: Ctx) => void) {
  if (alpha >= 0.999) {
    ctx.save();
    fn(ctx);
    ctx.restore();
    return;
  }
  const W = ctx.canvas.width;
  const Hh = ctx.canvas.height;
  scratch ??= document.createElement("canvas");
  if (scratch.width < W || scratch.height < Hh) {
    scratch.width = Math.max(scratch.width, W);
    scratch.height = Math.max(scratch.height, Hh);
  }
  const s = scratch.getContext("2d");
  if (!s) return;
  s.setTransform(1, 0, 0, 1, 0, 0);
  s.clearRect(0, 0, W, Hh);
  s.setTransform(ctx.getTransform());
  s.save();
  fn(s);
  s.restore();
  ctx.save();
  ctx.setTransform(1, 0, 0, 1, 0, 0);
  ctx.globalAlpha *= alpha;
  ctx.drawImage(scratch, 0, 0, W, Hh, 0, 0, W, Hh);
  ctx.restore();
}

export interface OutfitState {
  /** 0 = gone, 1 = fully on. Animated by the engine. */
  presence: number;
  /** Groovy's mailbox morph: items fade away as he turns into a box. */
  morph: number;
}

/** Turned round (a roll): what sits on his face is behind him. */
function faceTurnedAway(H: Head): boolean {
  return Math.cos(H.yaw) < 0;
}

function layerAlpha(st: OutfitState): number {
  const morphFade = 1 - Math.min(1, Math.max(0, (st.morph - 0.3) / 0.2));
  return morphFade * Math.min(1, st.presence * 2.5);
}

/** The item's way in: hats drop and settle, glasses slide down, neck items pop. */
function arrive(ctx: Ctx, item: Accessory, H: Head, p: number) {
  const posP = Ease.back(p);
  const slot = SLOT_OF[item];
  if (slot === "head") {
    const s = 0.85 + 0.15 * posP;
    ctx.translate(0, -(1 - posP) * H.ry);
    ctx.scale(s, s);
  } else if (slot === "face") {
    ctx.translate(0, -(1 - p) * 0.25 * H.ry);
  } else {
    const s = Math.max(0.001, 0.6 + 0.4 * posP);
    ctx.translate(0, H.ry * 0.85);
    ctx.scale(s, s);
    ctx.translate(0, -H.ry * 0.85);
  }
}

/** The board's eyes (Wardrobe.dc.html): what face items were drawn around. */
const BOARD_EYES = { l: 38, r: 62, y: 62 } as const;
/** How far a face item's art reaches beyond a lens on the board, in board units (arms excluded). */
const FACE_REACH = 24;
/** Half the width of a hat's art on the board, where it is narrower than his rim. */
/** Hats whose drawing sits above the board's rim line: how far (board units) to lower them onto his crown. */
const SEAT_DROP: Partial<Record<Accessory, number>> = { beretPin: 6, miniTopHat: 5, twigAntlers: -4 };
const HAT_HALF: Partial<Record<Accessory, number>> = { acornCap: 28, backwardsCap: 26, leafCrown: 31 };
/** The board point the pool ring hangs from: his middle. */
const ANCHOR = { middle: [50, 80] } as const;
/**
 * The board body (a 72×62 rounded rect, corner 22, at 14,30) at RIM_V and
 * COLLAR_V: the line's height and half width, mapped onto his rim and collar.
 */
const BOARD_RIM = { y: 61 + ART_RIM_V * 31, hw: 14 + Math.sqrt(22 * 22 - (52 - (61 + ART_RIM_V * 31)) ** 2) } as const;
const BOARD_COLLAR = { y: 61 + COLLAR_V * 31, hw: 14 + Math.sqrt(22 * 22 - (61 + COLLAR_V * 31 - 70) ** 2) } as const;

/** Hats and crowns whose rim goes round his head: the far half shows behind him. */
const RIMMED = new Set<Accessory>([
  "leafCrown", "acornCap", "mushroomCap", "flowerCrown", "bucketHat", "backwardsCap", "diamondCrown",
  "pumpkinCap", "bobbleBeanie", "eggshellHat", "strawSunHat", "watermelonCap",
]);
/** Neck items that go all the way round him: the back half shows behind him. */
const COLLARED = new Set<Accessory>([
  "bandana", "leafScarf", "seedPendant", "neckPhones", "goldChain", "flowerLei",
  "candyCornScarf", "knitStripeScarf", "jingleBellCollar", "daisyChain", "shellNecklace",
]);
/** Worn parts that hang or stand loose and swing the most: ears, stalks, antennae, pom-poms, antlers, wings. */
const LOOSE = new Set<Accessory>(["bunnyEarBand", "bobbleBeanie", "acornCap", "antenna", "twigAntlers", "batWingBand", "cloudBuddy", "beretPin", "littleGhostPal", "pastelRibbonBow"]);
/** Neck items that hang from a point and swing like a pendulum. */
const HANGING = new Set<Accessory>(["necktie", "seedPendant", "goldChain", "jingleBellCollar", "shellNecklace", "leafScarf", "candyCornScarf", "knitStripeScarf", "flowerLei", "bowTie"]);
/** Glasses with arms that run back along his head. */

/** The item's main colour, a shade darker: its far side, in shadow. */
function backColour(art: Art): string | null {
  const f = [...(art.front ?? []), ...(art.body ?? [])].find((sh) => typeof sh.f === "string" && /^#[0-9a-f]{6}$/i.test(sh.f))?.f;
  if (!f) return null;
  const n = parseInt(f.slice(1), 16);
  const d = (v: number) => Math.round(v * 0.62);
  return `rgb(${d(n >> 16)},${d((n >> 8) & 255)},${d(n & 255)})`;
}

/**
 * The parts of an item that sit behind his body (round 3H item 1): the far half
 * of a hat's rim, the back of a collar, the arms of glasses. Drawn before the
 * body, so only what shows past his outline is seen.
 */
function drawBackParts(ctx: Ctx, item: Accessory, art: Art, H: Head) {
  const slot = SLOT_OF[item];
  const col = backColour(art);
  if (!col) return;
  const A = headAnchors(H);
  // A dome hat covers the top of his head: its back is hidden by the hat itself, so nothing is drawn behind.
  if ((slot === "head" && RIMMED.has(item) && !CAP.has(item)) || (slot === "neck" && COLLARED.has(item))) {
    const r = slot === "head" ? A.rim : A.collar;
    const back = splitRing(ringPoints(H, r.cy, r.a * 1.04), false);
    ctx.strokeStyle = col;
    ctx.lineWidth = Math.max(1, r.b * (slot === "head" ? 0.7 : 0.9));
    ctx.lineCap = "round";
    ctx.lineJoin = "round";
    for (const run of back) {
      ctx.beginPath();
      run.forEach((q, i) => (i ? ctx.lineTo(q.x + r.cx, q.y) : ctx.moveTo(q.x + r.cx, q.y)));
      ctx.stroke();
    }
  }
  for (const st of wrapStrokes(item, H, A, art)) if (st.back) strokeRuns(ctx, st, false, 0, true);
    else if (!st.onTop) strokeRuns(ctx, st, false);
  if (item === "headphones") drawCups(ctx, art, H, A, false);
}

/** How an item narrows as he turns, never below 0.6 so nothing vanishes. */
export function narrowing(yaw: number, strength: number): number {
  return Math.max(0.6, 1 - (1 - Math.max(0, Math.cos(yaw))) * strength);
}

/**
 * Where a face item sits: the board's two eyes onto his (their middle, their
 * spacing, never under 0.6 of the full face's, and the line between them), so a
 * lens is always on its eye. What lies beyond a lens on the board (a visor's
 * ends, a patch's strap) is foreshortened with the turn so its outer edge stays
 * inside his outline: `kL` and `kR` scale the board left of the left lens and
 * right of the right lens.
 */
function faceFit(H: Head) {
  const sx = H.rx / 36;
  const sy = H.ry / 31;
  const [l, r] = H.eyes ?? [[-12 * sx, sy], [12 * sx, sy]];
  const front = Math.abs(12 * sx * 2) || 1;
  // His eyes sit on a sphere: looking up or down draws them closer together on screen (by
  // the cosine of that angle). Glasses don't shrink with that, so it is undone here.
  const near = Math.max(0.55, Math.cos(-0.12 + H.pitch));
  const span = Math.hypot(r[0] - l[0], r[1] - l[1]) / near;
  const full = H.eyes ? span / Math.max(0.05, Math.cos(H.yaw)) : front;
  const half = (BOARD_EYES.r - BOARD_EYES.l) / 2;
  // Owner, 6 Nov: when his eyes went low the glasses shrank with them, as if pasted on.
  // Glasses keep the size they have on his eyes at rest (2·sin 0.37·rx apart, engine.ts
  // EYE_SP); only turning narrows them, side to side.
  const rest = 0.7 * H.rx;
  const k = Math.max(span, full * 0.6, rest * Math.max(0.3, Math.cos(H.yaw))) / (BOARD_EYES.r - BOARD_EYES.l);
  const ky = Math.max(full, rest) / (BOARD_EYES.r - BOARD_EYES.l);
  const cx = (l[0] + r[0]) / 2;
  const cy = (l[1] + r[1]) / 2;
  const rot = Math.atan2(r[1] - l[1], r[0] - l[0]);
  const hw = halfWidthAt(cy, H.rx, H.ry, BODY_EXP) * 0.98;
  const side = (room: number) => Math.min(k, Math.max(0.1 * k, room) / FACE_REACH);
  return { cx, cy, rot, k, ky, kL: side(hw + cx - half * k), kR: side(hw - cx - half * k) };
}

// ── Things that go round him (round 3M item 3) ───────────────────────────────

/** `onTop`: lies over the top of his head (a headband), so it is never hidden by him. */
interface Stroke { pts: P3[]; color: string; lw: number; closed?: boolean; onTop?: boolean; clipBody?: boolean; clipOut?: boolean; back?: boolean }



/** The straps, bands and arms an item draws from his head model. `x` offsets are in body space. */
function wrapStrokes(item: Accessory, H: Head, A: Anchors, art: Art): Stroke[] {
  const ey = A.eyeLine;
  const R = H.R;
  const ry = H.ry;
  const dark = backColour(art) ?? "#222";
  switch (item) {
    case "piratePatch": {
      // The patch is on his right eye. One strap runs from it straight out to that side of his
      // head; the other goes up across his forehead, ABOVE his other eye, to the far side.
      // Both lie on his face and stop at his outline (clipped to his body), like a real strap.
      const span = Math.hypot(A.eyeR[0] - A.eyeL[0], A.eyeR[1] - A.eyeL[1]) || R * 0.8;
      const r = span * 0.34;
      const [px, py] = A.eyeR;
      const [lx] = A.eyeL;
      const wx = A.rim.cx;
      const y1 = py - r * 0.45;
      const hw1 = halfWidthAt(y1, H.rx, H.ry, BODY_EXP);
      const yT = py - r * 1.6;
      const hwT = halfWidthAt(yT, H.rx, H.ry, BODY_EXP);
      const lw = R * 0.05;
      return [
        { pts: curve(px + r * 0.8, py - r * 0.25, (px + wx + hw1) / 2, y1 - r * 0.1, wx + hw1 * 1.05, y1), color: "#1B1F26", lw, onTop: true, clipBody: true },
        { pts: curve(px - r * 0.55, py - r * 0.8, (px + lx) / 2, yT, wx - hwT * 1.05, yT), color: "#1B1F26", lw, onTop: true, clipBody: true },
      ];
    }
    case "glowVisor": {
      const a = halfWidthAt(ey, H.rx, H.ry, BODY_EXP);
      return [{ pts: ringPoints(H, ey, a * 0.93), color: "#2FBF5F", lw: ry * 0.3, closed: true }];
    }
    case "pilotGoggles": {
      const yc = A.rim.cy - 0.18 * ry;
      return [{ pts: ringPoints(H, yc, halfWidthAt(yc, H.rx, H.ry, BODY_EXP)), color: "#7A5230", lw: R * 0.07, closed: true }];
    }
    case "headphones": {
      // Over the top of his head from ear to ear, just outside his outline (clipped to outside him): so it
      // never crosses his face. As he turns, the far half tucks in behind his head with its cup.
      const earY = ey;
      const u = turnOf(H, A);
      const top: [number, number][] = [];
      for (let k = 0; k <= 120; k++) {
        const [x, y] = pillowXY((k / 120) * Math.PI * 2, H.rx, H.ry, BODY_EXP);
        if (y > earY * 1.06) continue;
        const far = Math.max(0, Math.sign(x) * u);
        const k2 = 1.06 + 0.02 * Math.max(0, -Math.sign(x) * u) - 0.14 * far;
        top.push([x * k2, y * (1.06 - 0.06 * far)]);
      }
      top.sort((p, q) => p[0] - q[0]);
      const wx = A.rim.cx;
      return [{ pts: top.map(([x, y]) => ({ x: x + wx, y, z: 1 })), color: "#2B2F36", lw: R * 0.11, onTop: true, clipOut: true }];
    }
    case "bunnyEarBand":
    case "batWingBand": {
      // A headband over his crown along his outline (never across his forehead); the ears or wings stand on it.
      const top: [number, number][] = [];
      for (let k = 0; k <= 120; k++) {
        const [x, y] = pillowXY((k / 120) * Math.PI * 2, H.rx, H.ry, BODY_EXP);
        if (y <= -0.42 * H.ry) top.push([x * 0.99, y * 0.99]);
      }
      top.sort((p, q) => p[0] - q[0]);
      const wx = A.rim.cx;
      return [{ pts: top.map(([x, y]) => ({ x: x + wx, y, z: 1 })), color: item === "bunnyEarBand" ? "#F2B8D4" : "#3A2A4A", lw: R * 0.07 }];
    }
    case "roundSpecs":
    case "shades":
    case "heartGlasses": {
      // Each arm runs level from the lens's outer edge to the side of his head and stops at
      // his outline, like glasses seen from the front: never down his cheek, never off his face.
      const span = Math.hypot(A.eyeR[0] - A.eyeL[0], A.eyeR[1] - A.eyeL[1]);
      const lens = span * 0.42;
      const wx = A.rim.cx;
      const out: Stroke[] = [];
      for (const [e, sd] of [[A.eyeL, -1], [A.eyeR, 1]] as const) {
        const y0 = e[1] - lens * 0.15;
        const hw = halfWidthAt(y0, H.rx, H.ry, BODY_EXP);
        const x0 = e[0] + sd * lens * 0.95;
        const x1 = wx + sd * hw * 1.05;
        if (sd * (x1 - x0) < lens * 0.1) continue; // this eye is at his edge: no room for an arm
        out.push({ pts: curve(x0, y0, (x0 + x1) / 2, y0 - lens * 0.06, x1, y0 - lens * 0.1, 6), color: dark, lw: Math.max(1, R * 0.045), onTop: true, clipBody: true });
      }
      return out;
    }
    default:
      return [];
  }
}

/**
 * How far he has turned, from where his eyes have moved: -1 (looking to his left of the screen)
 * … +1. The eyes slide towards the side that is turning away from us, so that side's ear (and
 * headphone cup) goes behind his head and the other side's comes round to the front.
 */
function turnOf(H: Head, A: Anchors): number {
  const mid = (A.eyeL[0] + A.eyeR[0]) / 2 - A.rim.cx;
  return Math.max(-1, Math.min(1, mid / (0.35 * H.rx)));
}

/** A quadratic curve as points on his front (z = 1): straps and arms that lie on his face. */
function curve(x0: number, y0: number, cx: number, cy: number, x1: number, y1: number, n = 14): P3[] {
  const out: P3[] = [];
  for (let i = 0; i <= n; i++) {
    const u = i / n;
    const a = (1 - u) * (1 - u);
    const b = 2 * u * (1 - u);
    const c = u * u;
    out.push({ x: a * x0 + b * cx + c * x1, y: a * y0 + b * cy + c * y1, z: 1 });
  }
  return out;
}


/** Draws a stroke's far pieces (back) or near pieces (front); the back ones are hidden by the body drawn over them. */
function strokeRuns(ctx: Ctx, st: Stroke, front: boolean, dx = 0, whole = false) {
  const runs = whole ? [st.pts] : st.closed ? splitRing(st.pts, front) : splitPath(st.pts, front);
  ctx.strokeStyle = st.color;
  ctx.lineWidth = Math.max(1, st.lw);
  ctx.lineCap = "round";
  ctx.lineJoin = "round";
  for (const run of runs) {
    ctx.beginPath();
    run.forEach((q, i) => (i ? ctx.lineTo(q.x + dx, q.y) : ctx.moveTo(q.x + dx, q.y)));
    ctx.stroke();
  }
}

function splitPath(pts: P3[], front: boolean): P3[][] {
  const runs: P3[][] = [];
  let cur: P3[] = [];
  for (const q of pts) {
    if (q.z >= 0 === front) cur.push(q);
    else if (cur.length) {
      runs.push(cur);
      cur = [];
    }
  }
  if (cur.length) runs.push(cur);
  return runs;
}

/** Headphone cups on his ears: the near one in front and bigger, the far one behind him, thinner as it turns away. */
function drawCups(ctx: Ctx, art: Art, H: Head, A: Anchors, front: boolean) {
  // On his ears, at eye height. Facing us, both sit on his outline. Turned, the near ear's cup
  // stays in front and grows a little; the far one goes behind his head (drawn behind him,
  // so only an edge peeks past his outline, then none at all).
  const shapes = art.front ?? [];
  const ax = halfWidthAt(A.eyeLine, H.rx, H.ry, BODY_EXP);
  const sx = H.rx / 36;
  const sy = H.ry / 31;
  const u = turnOf(H, A);
  for (const sd of [-1, 1]) {
    const far = Math.max(0, sd * u);
    const isFar = far > 0.2;
    if (isFar === front) continue;
    const cup = sd < 0 ? [shapes[0], shapes[2]] : [shapes[1], shapes[3]];
    const x = A.rim.cx + sd * (ax + sx * (1.5 - 7 * far));
    const w = 0.95 * (1 + 0.15 * Math.max(0, -sd * u)) * (1 - 0.35 * far);
    ctx.save();
    ctx.translate(x, A.eyeLine);
    ctx.scale(sx * w, sy * (1 + 0.08 * Math.max(0, -sd * u)));
    ctx.translate(-(sd < 0 ? 13.5 : 86.5), -60);
    drawShapes(ctx, cup.filter(Boolean) as Shape[]);
    ctx.restore();
  }
}

/**
 * Board space for an item, placed on its anchor (the caller drew nothing
 * yet). Exported for the placement test.
 */
export function placeItem(ctx: Ctx, item: Accessory, H: Head) {
  const sx = H.rx / 36;
  const sy = H.ry / 31;
  const slot = SLOT_OF[item];
  const wobbleX = H.physDx * H.rx * 0.05;
  const wobbleY = H.physDy * H.ry * 0.05;
  if (slot === "face") {
    const f = faceFit(H);
    ctx.translate(f.cx, f.cy);
    ctx.rotate(f.rot);
    ctx.scale(f.k, f.ky);
    ctx.translate(-(BOARD_EYES.l + BOARD_EYES.r) / 2, -BOARD_EYES.y);
    return;
  }
  if (item !== "poolRing" && (slot === "head" || slot === "neck")) {
    // The board's rim (or collar) line onto his: its middle and its width, so
    // the item's seat lies on his real outline at every turn and nod.
    const A = headAnchors(H);
    const ring = slot === "head" ? A.rim : A.collar;
    const seat = slot === "head" ? BOARD_RIM : BOARD_COLLAR;
    const kx = narrowing(H.yaw, slot === "head" ? 0.25 : 0.5);
    // Sized from the rim: a hat is at least 0.92 of his width there (round 3L item 4).
    const fit = slot === "head" ? Math.max(1, ((CAP.has(item) ? 1.06 : 0.92) * seat.hw) / (HAT_HALF[item] ?? seat.hw)) : 1;
    // The seat is the ring's front point on his head model, so it follows his turn and nod.
    const F = ringPoint(H, ring.cy, ring.a, 0);
    ctx.translate(ring.cx + F.x * (slot === "head" ? (CAP.has(item) ? 0.12 : 0.5) : 1), F.y + (item === "neckPhones" ? 8 * sy : 0)); // its cups hang low on his chest
    // Worn parts lag and swing from their seat: hats tip against the motion, dangling parts hang from it.
    const sw = H.swing ?? 0;
    ctx.rotate(slot === "head" ? -H.physDx * 0.1 - sw * (LOOSE.has(item) ? 0.9 : 0.3) : sw * (HANGING.has(item) ? 0.5 : 0.2));
    // Dangling parts stretch a little when he hops (the body's own squash already scales everything).
    const hop = slot === "neck" ? 1 + H.physDy * 0.12 : 1;
    ctx.scale((ring.a / seat.hw) * kx * fit, sy * (slot === "head" ? Math.min(fit, 1.15) : 1) * hop);
    ctx.translate(-50, -seat.y + (slot === "head" ? SEAT_DROP[item] ?? 0 : 0));
    return;
  }
  const [ax, ay] = ANCHOR.middle;
  ctx.translate(Math.sin(H.yaw) * H.rx * 0.3 + wobbleX, -Math.sin(H.pitch) * H.ry * 0.2 + wobbleY);
  ctx.translate((ax - 50) * sx, (ay - 61) * sy);
  ctx.scale(sx, sy);
  ctx.translate(-ax, -ay);
}

let bodyPath: { key: string; path: Path2D } | null = null;
function bodyOutline(H: Head): Path2D {
  const key = `${H.rx.toFixed(1)}|${H.ry.toFixed(1)}`;
  if (bodyPath?.key === key) return bodyPath.path;
  const path = new Path2D();
  for (let i = 0; i <= 64; i++) {
    const [x, y] = pillowXY((i / 64) * Math.PI * 2, H.rx, H.ry, BODY_EXP);
    if (i) path.lineTo(x, y);
    else path.moveTo(x, y);
  }
  path.closePath();
  bodyPath = { key, path };
  return path;
}

/**
 * Round 3L items 2 and 3: a soft shadow on his body where the item touches it,
 * along the rim's, the collar's or the frame's own curve; clipped to the body.
 */
function drawContactShadow(ctx: Ctx, item: Accessory, H: Head) {
  // A soft shade just under the near half of a hat's rim or a collar, following its own
  // curve on the head model; never a hard line, never on face items (they'd read as seams).
  if (H.R < 14) return;
  const slot = SLOT_OF[item];
  // Only hats that cover his whole crown (domes) and collars that go right round him:
  // a crown or a small hat is narrower than the rim ring, so a shade there reads as a seam.
  if (!((slot === "head" && CAP.has(item)) || (slot === "neck" && COLLARED.has(item)))) return;
  const A = headAnchors(H);
  const r = slot === "head" ? A.rim : A.collar;
  // Thin and tight against the item's edge, so it reads as contact, not as a band.
  const off = H.R * 0.025;
  const runs = splitRing(ringPoints(H, r.cy + off, r.a * 0.98), true);
  ctx.save();
  ctx.clip(bodyOutline(H));
  ctx.strokeStyle = "rgba(10,30,20,0.16)";
  ctx.lineWidth = H.R * 0.06;
  ctx.lineCap = "round";
  ctx.lineJoin = "round";
  ctx.shadowColor = "rgba(10,30,20,0.2)";
  ctx.shadowBlur = H.R * 0.06;
  for (const run of runs) {
    ctx.beginPath();
    run.forEach((q, i) => (i ? ctx.lineTo(q.x + r.cx, q.y) : ctx.moveTo(q.x + r.cx, q.y)));
    ctx.stroke();
  }
  ctx.restore();
}

function drawItem(ctx: Ctx, item: Accessory, art: Art, H: Head, layers: readonly ("behind" | "body" | "front")[]) {
  if (SLOT_OF[item] === "face") {
    const f = faceFit(H);
    if (f.kL < f.k * 0.99 || f.kR < f.k * 0.99) {
      drawFaceBands(ctx, art, layers, f);
      return;
    }
  }
  placeItem(ctx, item, H);
  for (const l of layers) drawShapes(ctx, art[l]);
}

/** A face item in three board bands (left of the left lens, between, right of the right lens), each at its own width. */
function drawFaceBands(ctx: Ctx, art: Art, layers: readonly ("behind" | "body" | "front")[], f: ReturnType<typeof faceFit>) {
  const h = (BOARD_EYES.r - BOARD_EYES.l) / 2;
  const bands: [number, number, number, number, number][] = [
    // [clip from, clip to, board x held in place, its offset from the middle, scale]
    [-1000, BOARD_EYES.l, BOARD_EYES.l, -h * f.k, f.kL],
    [BOARD_EYES.l - 0.2, BOARD_EYES.r + 0.2, 50, 0, f.k],
    [BOARD_EYES.r, 1000, BOARD_EYES.r, h * f.k, f.kR],
  ];
  for (const [from, to, at, off, kx] of bands) {
    ctx.save();
    ctx.translate(f.cx, f.cy);
    ctx.rotate(f.rot);
    ctx.translate(off, 0);
    ctx.scale(kx, f.ky);
    ctx.translate(-at, -BOARD_EYES.y);
    ctx.beginPath();
    ctx.rect(from, -1000, to - from, 2000);
    ctx.clip();
    for (const l of layers) drawShapes(ctx, art[l]);
    ctx.restore();
  }
}

/**
 * The parts behind Groovy's body. `ctx` is in body space (translated to the body
 * centre, tilted and squashed exactly like the body).
 */
export function drawOutfitBehind(ctx: Ctx, outfit: Outfit, H: Head, st: OutfitState) {
  if (outfit === "none") return;
  const art = ITEM_ART[outfit];
  const alpha = layerAlpha(st);
  if (!art || alpha <= 0.005) return;
  const face = SLOT_OF[outfit] === "face";
  // Turned away, his glasses are behind him; anything that is always behind stays there.
  const layers = face && faceTurnedAway(H) ? (["behind", "body", "front"] as const) : (["behind"] as const);
  const back = !(face && faceTurnedAway(H));
  if (!back && !layers.some((l) => art[l]?.length)) return;
  ctx.save();
  arrive(ctx, outfit, H, st.presence);
  withLayer(ctx, alpha, (l) => {
    // His body is glassy, so anything drawn behind it would show through it as a
    // pale band or a grey seam: what is behind him only shows past his outline.
    l.save();
    l.clip(outsideBody(H), "evenodd");
    if (RING_CROWN.has(outfit) || CAP.has(outfit)) {
      if (RING_CROWN.has(outfit)) drawRingCrown(l, outfit, H, false);
      else drawCapBack(l, outfit, H);
      l.restore();
      return;
    }
    if (back) {
      l.save();
      drawBackParts(l, outfit, art, H);
      l.restore();
    }
    drawItem(l, outfit, art, H, layers);
    l.restore();
  });
  ctx.restore();
}

/**
 * Crowns that go right round his head, drawn on the head model (not from the board): a vine or
 * stem ring with leaves or flowers spaced all the way round. The ones facing us are drawn over
 * him (so they wrap to his sides, no bare skin there); the ones round the back are behind him.
 */
const RING_CROWN = new Set<Accessory>(["leafCrown", "flowerCrown"]);
const PETALS = ["#FF9FC6", "#FFD84A", "#FFFFFF", "#B79CFF"];
function drawRingCrown(ctx: Ctx, item: Accessory, H: Head, front: boolean) {
  const r = headAnchors(H).rim;
  const a = r.a * 1.02;
  const yc = r.cy - H.ry * 0.04;
  const R = H.R;
  const depth = DEPTH * a;
  // The stem ring itself.
  const ringPts = ringPoints(H, yc, a, 64);
  ctx.save();
  ctx.lineCap = "round";
  ctx.lineJoin = "round";
  ctx.strokeStyle = item === "leafCrown" ? "#7A5230" : "#3A8F4E";
  ctx.lineWidth = R * (item === "leafCrown" ? 0.05 : 0.035);
  for (const run of splitRing(ringPts, front)) {
    ctx.beginPath();
    run.forEach((q, i) => (i ? ctx.lineTo(q.x + r.cx, q.y) : ctx.moveTo(q.x + r.cx, q.y)));
    ctx.stroke();
  }
  // The leaves or flowers, back to front.
  const n = item === "leafCrown" ? 18 : 11;
  const spots: { q: P3; i: number }[] = [];
  for (let i = 0; i < n; i++) {
    const q = ringPoint(H, yc, a, (i / n) * Math.PI * 2);
    if (q.z >= 0 === front) spots.push({ q, i });
  }
  spots.sort((p, q) => p.q.z - q.q.z);
  for (const { q, i } of spots) {
    const near = Math.max(0, Math.min(1, (q.z / depth + 1) / 2));
    const k = R * (0.7 + 0.3 * near);
    const x = q.x + r.cx;
    const side = q.x / a; // -1 at his left, +1 at his right
    ctx.save();
    ctx.translate(x, q.y);
    if (item === "leafCrown") {
      // Each leaf stands up from the vine, leaning out towards his sides.
      ctx.rotate(side * 0.75 + (i % 2 ? 0.18 : -0.18));
      const g = ctx.createLinearGradient(0, 0, 0, -k * 0.42);
      g.addColorStop(0, "#2E9E55");
      g.addColorStop(1, "#46EB78");
      ctx.fillStyle = g;
      ctx.beginPath();
      ctx.moveTo(0, 0);
      ctx.quadraticCurveTo(k * 0.13, -k * 0.21, 0, -k * 0.42);
      ctx.quadraticCurveTo(-k * 0.13, -k * 0.21, 0, 0);
      ctx.fill();
      ctx.strokeStyle = "rgba(20,90,45,0.55)";
      ctx.lineWidth = Math.max(0.6, k * 0.012);
      ctx.beginPath();
      ctx.moveTo(0, -k * 0.02);
      ctx.lineTo(0, -k * 0.35);
      ctx.stroke();
      if (i === 0) {
        ctx.fillStyle = "#E2564B";
        ctx.beginPath();
        ctx.arc(0, k * 0.01, k * 0.05, 0, Math.PI * 2);
        ctx.fill();
      }
    } else {
      // A five-petal flower facing out, a little flattened by the view.
      ctx.scale(1, 0.86);
      const pr = k * 0.1;
      ctx.fillStyle = PETALS[i % PETALS.length];
      for (let p = 0; p < 5; p++) {
        const t = (p / 5) * Math.PI * 2 - Math.PI / 2;
        ctx.beginPath();
        ctx.arc(Math.cos(t) * pr * 1.05, Math.sin(t) * pr * 1.05, pr, 0, Math.PI * 2);
        ctx.fill();
      }
      ctx.fillStyle = "#FF8A2F";
      ctx.beginPath();
      ctx.arc(0, 0, pr * 0.7, 0, Math.PI * 2);
      ctx.fill();
    }
    ctx.restore();
  }
  ctx.restore();
}

/**
 * Caps that are worn ON his head, drawn on the head model rather than pasted from the board:
 * the cap is the top of his head itself, a little larger, cut off along the front of a ring
 * round his head (so its edge curves round him and turns with him), with its own details
 * (scales, ribs, spots) lying on that surface. Nothing behind, no fill under it.
 */
const CAP = new Set<Accessory>([
  "acornCap", "pumpkinCap", "mushroomCap", "bucketHat", "bobbleBeanie", "eggshellHat", "watermelonCap", "backwardsCap", "strawSunHat",
]);
/**
 * seat: the edge's height (× ry); s: its width against his head there; h: the dome's height above it (× ry);
 * lobes: a pumpkin's bulges; brim: a flat brim round the edge, its width against the edge's; zig: a
 * zigzag edge's teeth; peak: a cap's peak at the back of his head.
 */
interface CapForm { seat: number; s: number; h: number; lobes: number; brim?: number; zig?: number; peak?: boolean }
const CAP_FORM: Record<string, CapForm> = {
  acornCap: { seat: -0.4, s: 1.07, h: 0.78, lobes: 0 },
  pumpkinCap: { seat: -0.38, s: 1.1, h: 0.82, lobes: 7 },
  mushroomCap: { seat: -0.46, s: 1.34, h: 0.88, lobes: 0 },
  bucketHat: { seat: -0.44, s: 1.06, h: 0.6, lobes: 0, brim: 1.42 },
  strawSunHat: { seat: -0.5, s: 1.04, h: 0.48, lobes: 0, brim: 1.9 },
  bobbleBeanie: { seat: -0.32, s: 1.08, h: 0.86, lobes: 0 },
  eggshellHat: { seat: -0.42, s: 1.06, h: 0.74, lobes: 0, zig: 11 },
  watermelonCap: { seat: -0.4, s: 1.08, h: 0.74, lobes: 0 },
  backwardsCap: { seat: -0.42, s: 1.07, h: 0.7, lobes: 0, peak: true },
};
/**
 * What grows on top of his head (Grove's sprout and bonsai, Blaze's flame) comes up through
 * a hat instead of hiding under it (owner, 6 Nov: on most headwear you couldn't see it before
 * stage 6). This is how far above his head's top the hat reaches, in px: the growth is drawn
 * that much higher, over the hat. Crowns, bands and ears leave room: nothing to lift.
 */
export function growthLift(items: readonly Outfit[], H: Head): number {
  let lift = 0;
  for (const it of items) {
    if (it === "none" || SLOT_OF[it] !== "head") continue;
    const c = CAP_FORM[it];
    const up = c ? c.h - (1 + c.seat) + 0.03 : it === "miniTopHat" ? 0.4 : it === "beretPin" ? 0.16 : it === "headphones" || it === "pilotGoggles" ? 0.08 : 0;
    lift = Math.max(lift, up * H.ry);
  }
  return lift;
}

/** Each cap's colours: lit, middle, in shadow, and the lip where it sits on him. */
const CAP_COL: Record<string, [string, string, string, string]> = {
  acornCap: ["#C58A4E", "#9A6232", "#6A3F1C", "#5A3417"],
  pumpkinCap: ["#FFB25C", "#F57F1F", "#C95A0E", "#B9540C"],
  mushroomCap: ["#FF7A6E", "#E2443A", "#A9261F", "#9E231C"],
  bucketHat: ["#F4E6C0", "#E0CC98", "#B9A56F", "#8C7A47"],
  strawSunHat: ["#F8E7A8", "#E8C774", "#C9A24E", "#A8843A"],
  bobbleBeanie: ["#FF7A7E", "#E5484D", "#B02A32", "#8F1F27"],
  eggshellHat: ["#FFFFFF", "#F3EEF7", "#D9D0E3", "#B79CFF"],
  watermelonCap: ["#FF8A94", "#FF5C6C", "#D63A4C", "#2E7A38"],
  backwardsCap: ["#FF7A82", "#F0505A", "#B83640", "#9E2E37"],
};
/** How round the dome is: 2 is an ellipse, higher is boxier (his head is 3). */
const CAP_P = 2.3;

/** A point on the cap's surface: `f` 0 at its edge … 1 at its top, `t` round him (0 = the front). */
function capPoint(H: Head, cx: number, seatY: number, a: number, h: number, f: number, t: number): P3 {
  const up = Math.sin((f * Math.PI) / 2);
  const y = seatY - h * up;
  const ay = a * Math.pow(Math.max(0, 1 - Math.pow(up, CAP_P)), 1 / CAP_P);
  const q = ringPoint(H, y, Math.max(0.5, ay), t);
  return { x: q.x + cx, y: q.y, z: q.z };
}

function capPath(H: Head, c: CapForm): { path: Path2D; front: P3[]; seatY: number; topY: number; cx: number; a: number; h: number } {
  const A = headAnchors(H);
  const cx = A.rim.cx;
  const seatY = c.seat * H.ry + H.physDy * H.ry * 0.05;
  const a = halfWidthAt(seatY, H.rx, H.ry, BODY_EXP) * c.s;
  const h = c.h * H.ry;
  const front = (splitRing(ringPoints(H, seatY, a, 72), true)[0] ?? []).slice().sort((p, q) => p.x - q.x);
  if (c.zig) {
    // A cracked shell: its edge zigzags (teeth up and down along the front of the ring).
    for (const q of front) {
      const u = ((q.x / a + 1) * c.zig) % 2;
      q.y -= H.R * 0.09 * (u < 1 ? u : 2 - u);
    }
  }
  const path = new Path2D();
  if (front.length) {
    path.moveTo(front[0].x + cx, front[0].y);
    for (const q of front) path.lineTo(q.x + cx, q.y);
  }
  // The dome over the top, right to left, from the ends of the front edge.
  const N = 96;
  for (let k = 0; k <= N; k++) {
    const x = a * (1 - (2 * k) / N);
    let up = Math.pow(Math.max(0, 1 - Math.pow(Math.abs(x / a), CAP_P)), 1 / CAP_P);
    let xx = x;
    if (c.lobes) {
      // A pumpkin's lobes: its outline bulges between the ribs.
      const bump = 1 + 0.04 * Math.abs(Math.sin((x / a) * c.lobes * 0.5 * Math.PI));
      xx *= bump;
      up *= bump;
    }
    path.lineTo(xx + cx, seatY - h * up);
  }
  path.closePath();
  const fr = front.map((q) => ({ x: q.x + cx, y: q.y, z: q.z }));
  return { path, front: fr, seatY, topY: seatY - h, cx, a, h };
}

function drawCap(ctx: Ctx, item: Accessory, H: Head) {
  const c = CAP_FORM[item];
  const { path, front, seatY, topY, cx, a, h } = capPath(H, c);
  const R = H.R;
  const w = a;
  const line = (pts: P3[]) => {
    ctx.beginPath();
    pts.forEach((q, i) => (i ? ctx.lineTo(q.x, q.y) : ctx.moveTo(q.x, q.y)));
  };
  const turn = Math.sin(H.yaw);
  ctx.save();
  // The cap itself, lit from the top left.
  const g = ctx.createRadialGradient(cx - w * 0.35, topY + (seatY - topY) * 0.25, R * 0.1, cx, seatY, w * 1.25);
  const [cHi, cMid, cLo, cLip] = CAP_COL[item];
  // A brim's front half lies over his forehead, under the dome (its back half is behind him).
  if (c.brim) drawBrim(ctx, H, cx, seatY, a * c.brim, true, cMid, cLip);
  g.addColorStop(0, cHi);
  g.addColorStop(0.58, cMid);
  g.addColorStop(1, cLo);
  ctx.fillStyle = g;
  ctx.fill(path);
  ctx.save();
  ctx.clip(path);
  ctx.lineCap = "round";
  ctx.lineJoin = "round";
  if (item === "acornCap") {
    // Rows of little scales, zigzags round the cap, only on the side facing us.
    ctx.strokeStyle = "rgba(70,38,14,0.55)";
    ctx.lineWidth = Math.max(0.8, R * 0.03);
    for (let row = 0; row < 5; row++) {
      const f0 = 0.08 + row * 0.18;
      const pts: P3[] = [];
      for (let k = 0; k <= 28; k++) {
        const t = -Math.PI / 2 + (k / 28) * Math.PI - turn * 0.6;
        const q = capPoint(H, cx, seatY, a, h, f0 + (k % 2 ? 0.09 : 0), t);
        if (q.z > 0) pts.push(q);
      }
      if (pts.length > 1) { line(pts); ctx.stroke(); }
    }
  } else if (item === "pumpkinCap") {
    // Ribs from the edge up to the stem, curving round the cap: they turn with him.
    ctx.strokeStyle = "rgba(170,70,10,0.5)";
    ctx.lineWidth = Math.max(0.8, R * 0.035);
    for (let r = -3; r <= 3; r++) {
      const t = r * 0.42 - turn * 0.6;
      const pts: P3[] = [];
      for (let k = 0; k <= 12; k++) {
        const q = capPoint(H, cx, seatY, a, h, k / 12, t);
        if (q.z > 0) pts.push(q);
      }
      if (pts.length > 1) { line(pts); ctx.stroke(); }
    }
  } else if (item !== "mushroomCap") {
    drawCapDetails(ctx, item, H, cx, seatY, a, h);
  } else {
    // White spots lying on the cap, smaller as they turn away.
    const SPOTS: [number, number, number][] = [[0.25, 0, 1], [0.3, 0.9, 0.8], [0.3, -0.95, 0.85], [0.6, 0.45, 0.9], [0.6, -0.5, 0.75], [0.82, 0.05, 0.7], [0.2, 1.7, 0.7], [0.22, -1.75, 0.7], [0.55, 1.4, 0.6], [0.55, -1.4, 0.6]];
    ctx.fillStyle = "#FFF7F0";
    for (const [f, t0, sz] of SPOTS) {
      const q = capPoint(H, cx, seatY, a, h, f, t0 - turn * 0.6);
      if (q.z <= 0.05 * w) continue;
      const k = Math.min(1, q.z / (0.8 * w)) ;
      ctx.beginPath();
      ctx.ellipse(q.x, q.y, R * 0.14 * sz * (0.45 + 0.55 * k), R * 0.115 * sz, 0, 0, Math.PI * 2);
      ctx.fill();
    }
  }
  // A soft highlight near the top left.
  const hl = ctx.createRadialGradient(cx - w * 0.3, topY + (seatY - topY) * 0.3, 0, cx - w * 0.3, topY + (seatY - topY) * 0.3, w * 0.45);
  hl.addColorStop(0, "rgba(255,255,255,0.28)");
  hl.addColorStop(1, "rgba(255,255,255,0)");
  ctx.fillStyle = hl;
  ctx.fill(path);
  ctx.restore();
  // The edge where it sits on him: a darker lip along the front of the ring.
  if (front.length > 1) {
    ctx.strokeStyle = cLip;
    ctx.lineWidth = R * (item === "mushroomCap" || item === "eggshellHat" ? 0.05 : 0.07);
    line(front);
    ctx.stroke();
  }
  // What grows from the top: the acorn's stalk, the pumpkin's stem and leaf. The mushroom has none.
  if (item === "bobbleBeanie") {
    // The pompom on top, lit from the top left, with a few knit tufts.
    const tip = capPoint(H, cx, seatY, a, h, 1, 0);
    const pr = R * 0.2;
    const pg = ctx.createRadialGradient(tip.x - pr * 0.4, tip.y - pr * 1.2, pr * 0.1, tip.x, tip.y - pr * 0.7, pr * 1.2);
    pg.addColorStop(0, "#FFFFFF");
    pg.addColorStop(1, "#D9DCE2");
    ctx.fillStyle = pg;
    ctx.beginPath();
    ctx.arc(tip.x, tip.y - pr * 0.7, pr, 0, Math.PI * 2);
    ctx.fill();
  } else if (item === "acornCap" || item === "pumpkinCap") {
    const tip = capPoint(H, cx, seatY, a, h, 1, 0);
    const bx = tip.x + turn * w * 0.12;
    const by = topY + R * 0.03;
    ctx.strokeStyle = item === "acornCap" ? "#6B4423" : "#4E7A2E";
    ctx.lineWidth = R * (item === "acornCap" ? 0.07 : 0.1);
    ctx.beginPath();
    ctx.moveTo(bx, by);
    ctx.quadraticCurveTo(bx + R * 0.02, by - R * 0.16, bx + R * 0.1, by - R * 0.24);
    ctx.stroke();
    if (item === "pumpkinCap") {
      ctx.fillStyle = "#5FB04A";
      ctx.beginPath();
      ctx.ellipse(bx + R * 0.2, by - R * 0.12, R * 0.13, R * 0.06, -0.4, 0, Math.PI * 2);
      ctx.fill();
    }
  }
  ctx.restore();
}

/** A flat brim round a cap's edge: its front half (`front`) over him, or the whole of it behind him. */
function drawBrim(ctx: Ctx, H: Head, cx: number, seatY: number, ab: number, front: boolean, fill: string, edge: string) {
  const y = seatY + H.ry * 0.03;
  const pts = ringPoints(H, y, ab, 72);
  ctx.save();
  ctx.beginPath();
  if (front) {
    const run = (splitRing(pts, true)[0] ?? []).slice().sort((p, q) => p.x - q.x);
    if (run.length < 2) { ctx.restore(); return; }
    run.forEach((q, i) => (i ? ctx.lineTo(q.x + cx, q.y) : ctx.moveTo(q.x + cx, q.y)));
  } else {
    pts.forEach((q, i) => (i ? ctx.lineTo(q.x + cx, q.y) : ctx.moveTo(q.x + cx, q.y)));
  }
  ctx.closePath();
  ctx.fillStyle = front ? fill : edge;
  ctx.fill();
  if (front) {
    ctx.strokeStyle = edge;
    ctx.lineWidth = H.R * 0.035;
    ctx.stroke();
  }
  ctx.restore();
}

/** What lies behind him for a cap: the back of a brim, a backwards cap's peak. Only past his outline shows. */
function drawCapBack(ctx: Ctx, item: Accessory, H: Head) {
  const c = CAP_FORM[item];
  if (!c.brim && !c.peak) return;
  const { seatY, cx, a } = capPath(H, c);
  const [, cMid, cLo, cLip] = CAP_COL[item];
  if (c.brim) drawBrim(ctx, H, cx, seatY, a * c.brim, false, cMid, cLo);
  if (c.peak) {
    // The peak sticks out from the back of the edge and turns with him.
    const y = seatY + H.ry * 0.02;
    const inner: P3[] = [];
    const outer: P3[] = [];
    for (let k = 0; k <= 16; k++) {
      const t = Math.PI + (k / 16 - 0.5) * 1.5;
      inner.push(ringPoint(H, y, a, t));
      outer.push(ringPoint(H, y, a * 1.75, Math.PI + (k / 16 - 0.5) * 1.1));
    }
    ctx.beginPath();
    [...inner, ...outer.reverse()].forEach((q, i) => (i ? ctx.lineTo(q.x + cx, q.y) : ctx.moveTo(q.x + cx, q.y)));
    ctx.closePath();
    ctx.fillStyle = cLo;
    ctx.fill();
    ctx.strokeStyle = cLip;
    ctx.lineWidth = H.R * 0.035;
    ctx.stroke();
  }
}

/** Details lying on a cap's surface (only the side facing us): stitches, knit ribs, a cuff, a ribbon, a rind, seeds, panels. */
function drawCapDetails(ctx: Ctx, item: Accessory, H: Head, cx: number, seatY: number, a: number, h: number) {
  const R = H.R;
  const turn = Math.sin(H.yaw);
  const pt = (f: number, t: number) => capPoint(H, cx, seatY, a, h, f, t - turn * 0.6);
  const path = (pts: P3[]) => {
    ctx.beginPath();
    pts.forEach((q, i) => (i ? ctx.lineTo(q.x, q.y) : ctx.moveTo(q.x, q.y)));
  };
  /** A line round the cap at height f, the part facing us. */
  const round = (f: number) => {
    // In order round him, then the one unbroken run facing us (sorting by x folded the line
    // back on itself near his sides: the watermelon's white rind showed as a blob there).
    const all: P3[] = [];
    for (let k = 0; k < 64; k++) all.push(pt(f, -Math.PI + (k / 64) * Math.PI * 2));
    const start = all.findIndex((q) => q.z <= 0);
    if (start < 0) return all;
    const ring = [...all.slice(start), ...all.slice(0, start)];
    let best: P3[] = [];
    let run: P3[] = [];
    for (const q of ring) {
      if (q.z > 0) run.push(q);
      else {
        if (run.length > best.length) best = run;
        run = [];
      }
    }
    if (run.length > best.length) best = run;
    return best;
  };
  /** A line from the edge up towards the top at angle t (a meridian). */
  const meridian = (t: number, f0: number, f1: number) => {
    const out: P3[] = [];
    for (let k = 0; k <= 12; k++) {
      const q = pt(f0 + ((f1 - f0) * k) / 12, t);
      if (q.z > 0) out.push(q);
    }
    return out;
  };
  const spots = (list: [number, number, number][], colour: string, size: number) => {
    ctx.fillStyle = colour;
    for (const [f, t, sz] of list) {
      const q = pt(f, t);
      if (q.z <= 0.05 * a) continue;
      const k = Math.min(1, q.z / (0.8 * a));
      ctx.beginPath();
      ctx.ellipse(q.x, q.y, R * size * sz * (0.45 + 0.55 * k), R * size * sz * 1.2, 0, 0, Math.PI * 2);
      ctx.fill();
    }
  };
  ctx.lineCap = "round";
  ctx.lineJoin = "round";
  if (item === "bucketHat" || item === "strawSunHat") {
    if (item === "strawSunHat") {
      // The ribbon round the crown, just above the brim.
      ctx.strokeStyle = "#3FC1C9";
      ctx.lineWidth = R * 0.12;
      path(round(0.1));
      ctx.stroke();
      ctx.strokeStyle = "rgba(160,120,40,0.35)";
      ctx.lineWidth = Math.max(0.8, R * 0.02);
      for (const f of [0.4, 0.62, 0.82]) { path(round(f)); ctx.stroke(); }
    } else {
      // Two rings of stitching.
      ctx.strokeStyle = "rgba(120,100,50,0.6)";
      ctx.lineWidth = Math.max(0.8, R * 0.022);
      ctx.setLineDash([R * 0.05, R * 0.05]);
      for (const f of [0.22, 0.5]) { path(round(f)); ctx.stroke(); }
      ctx.setLineDash([]);
    }
  } else if (item === "bobbleBeanie") {
    // Knit ribs on meridians, then the folded cuff over them.
    ctx.strokeStyle = "rgba(120,10,20,0.32)";
    ctx.lineWidth = Math.max(0.8, R * 0.03);
    for (let r = -8; r <= 8; r++) {
      const m = meridian(r * 0.2, 0.26, 0.97);
      if (m.length > 1) { path(m); ctx.stroke(); }
    }
    const lo = round(0);
    const hi = round(0.26);
    if (lo.length > 1 && hi.length > 1) {
      ctx.beginPath();
      lo.forEach((q, i) => (i ? ctx.lineTo(q.x, q.y) : ctx.moveTo(q.x, q.y)));
      for (const q of [...hi].reverse()) ctx.lineTo(q.x, q.y);
      ctx.closePath();
      ctx.fillStyle = "#F4F5F7";
      ctx.fill();
      ctx.strokeStyle = "rgba(150,150,165,0.45)";
      ctx.lineWidth = Math.max(0.8, R * 0.025);
      for (let r = -12; r <= 12; r++) {
        const m = meridian(r * 0.14, 0.02, 0.24);
        if (m.length > 1) { path(m); ctx.stroke(); }
      }
    }
  } else if (item === "eggshellHat") {
    // Little painted speckles and one crack.
    spots([[0.3, 0.2, 1], [0.55, -0.6, 0.9], [0.5, 0.9, 0.8], [0.75, 0.1, 0.8], [0.3, -1.2, 0.8]], "#8FD6C3", 0.07);
    spots([[0.42, -0.2, 0.9], [0.65, 0.55, 0.8], [0.28, 1.3, 0.7]], "#F7A9C8", 0.07);
    spots([[0.6, -1.1, 0.8], [0.38, 0.65, 0.7]], "#F2C744", 0.07);
    ctx.strokeStyle = "rgba(160,140,190,0.8)";
    ctx.lineWidth = Math.max(0.8, R * 0.025);
    const crack = [pt(0.55, -0.35), pt(0.62, -0.22), pt(0.58, -0.08), pt(0.68, 0.05)].filter((q) => q.z > 0);
    if (crack.length > 1) { path(crack); ctx.stroke(); }
  } else if (item === "watermelonCap") {
    // The rind at the edge (green, then a pale line), black seeds on the red.
    ctx.strokeStyle = "#3E9C4A";
    ctx.lineWidth = R * 0.16;
    path(round(0.03));
    ctx.stroke();
    ctx.strokeStyle = "#F4FFF0";
    ctx.lineWidth = R * 0.045;
    path(round(0.16));
    ctx.stroke();
    spots([[0.4, 0, 1], [0.45, 0.7, 0.9], [0.45, -0.7, 0.9], [0.7, 0.35, 0.8], [0.7, -0.35, 0.8], [0.35, 1.35, 0.8], [0.35, -1.35, 0.8], [0.9, 0, 0.7]], "#22302A", 0.05);
  } else if (item === "backwardsCap") {
    // Six panels meeting at a button; at the front (his back of the cap faces us) the strap opening.
    ctx.strokeStyle = "rgba(120,20,30,0.45)";
    ctx.lineWidth = Math.max(0.8, R * 0.028);
    for (const t of [-1.05, 0, 1.05]) {
      const m = meridian(t, 0.05, 0.98);
      if (m.length > 1) { path(m); ctx.stroke(); }
    }
    const arch: P3[] = [];
    for (let k = 0; k <= 12; k++) {
      const u = k / 12;
      arch.push(pt(Math.sin(u * Math.PI) * 0.3, (u - 0.5) * 0.7));
    }
    const vis = arch.filter((q) => q.z > 0);
    if (vis.length > 1) {
      path(vis);
      ctx.fillStyle = "rgba(40,10,15,0.35)";
      ctx.fill();
      ctx.strokeStyle = "#2B2F36";
      ctx.lineWidth = R * 0.05;
      ctx.stroke();
    }
    const top = pt(1, 0);
    ctx.fillStyle = "#C93C45";
    ctx.beginPath();
    ctx.arc(top.x, top.y + R * 0.02, R * 0.06, 0, Math.PI * 2);
    ctx.fill();
  }
}

let outside: { key: string; path: Path2D } | null = null;
/** Everything except his body: a big box with his outline cut out (for an even-odd clip). */
function outsideBody(H: Head): Path2D {
  const key = `${H.rx.toFixed(1)}|${H.ry.toFixed(1)}`;
  if (outside?.key === key) return outside.path;
  const path = new Path2D();
  const big = (H.rx + H.ry) * 8;
  path.rect(-big, -big, big * 2, big * 2);
  path.addPath(bodyOutline(H));
  outside = { key, path };
  return path;
}

/** The parts in front of Groovy, drawn after the body and the eyes. */
export function drawOutfitFront(ctx: Ctx, outfit: Outfit, H: Head, st: OutfitState) {
  if (outfit === "none") return;
  const art = ITEM_ART[outfit];
  if (!art || (SLOT_OF[outfit] === "face" && faceTurnedAway(H))) return;
  const alpha = layerAlpha(st);
  if (alpha <= 0.005) return;
  ctx.save();
  arrive(ctx, outfit, H, st.presence);
  // The board puts glasses that hide the eyes under them; on him they go over.
  withLayer(ctx, alpha, (l) => {
    drawContactShadow(l, outfit, H);
    if (CAP.has(outfit)) {
      drawCap(l, outfit, H);
      return;
    }
    const A = headAnchors(H);
    for (const st of wrapStrokes(outfit, H, A, art)) {
      if (st.back) continue;
      l.save();
      if (st.clipBody) l.clip(bodyOutline(H));
      // Drawn over his glow but only past his outline: what dips inside it is behind his head.
      if (st.clipOut) l.clip(outsideBody(H), "evenodd");
      strokeRuns(l, st, true, 0, st.onTop);
      l.restore();
    }
    if (outfit === "headphones") drawCups(l, art, H, A, true);
    else if (RING_CROWN.has(outfit)) drawRingCrown(l, outfit, H, true);
    else if (SLOT_OF[outfit] === "face") {
      // Whatever sits on his face stays on his face: nothing past his outline.
      l.save();
      l.clip(bodyOutline(H));
      drawItem(l, outfit, art, H, ["body", "front"]);
      l.restore();
    } else drawItem(l, outfit, art, H, ["body", "front"]);
  });
  ctx.restore();
}

// ── Wardrobe icons ────────────────────────────────────────────────────────────

/** The board's body: a 72×62 rounded rect at (14, 30). */
const ICON_BODY = "M36 30H64A22 22 0 0 1 86 52V70A22 22 0 0 1 64 92H36A22 22 0 0 1 14 70V52A22 22 0 0 1 36 30Z";
let iconBody: Path2D | null = null;

/** A little Groovy wearing `item`, as on the boards, in a `size`×`size` icon. */
function iconGroovy(ctx: Ctx, size: number, item: Accessory) {
  const art = ITEM_ART[item];
  // The boards' view, -8…104 high: hats reach up to about y -4, neck items down to 100.
  const k = size / 112;
  ctx.save();
  ctx.translate(size / 2 - 50 * k, 8 * k);
  ctx.scale(k, k);
  drawShapes(ctx, art?.behind);
  iconBody ??= new Path2D(ICON_BODY);
  const g = ctx.createLinearGradient(70, 30, 30, 92);
  g.addColorStop(0, "#F1F3F5");
  g.addColorStop(1, "#C6C9CF");
  ctx.fillStyle = g;
  ctx.fill(iconBody);
  ctx.fillStyle = "#1A1412";
  for (const ex of [38, 62]) {
    ctx.beginPath();
    ctx.ellipse(ex, 62, 5.5, 4, 0, 0, Math.PI * 2);
    ctx.fill();
  }
  ctx.save();
  ctx.clip(iconBody);
  drawShapes(ctx, art?.body, "clipped");
  drawShapes(ctx, art?.front, "clipped");
  ctx.restore();
  drawShapes(ctx, art?.body, "free");
  drawShapes(ctx, art?.front, "free");
  ctx.restore();
}

/** One wardrobe button's picture; "none" is a crossed-out circle. */
export function drawWardrobeIcon(ctx: Ctx, size: number, selection: Outfit) {
  ctx.clearRect(0, 0, size, size);
  if (selection === "none") {
    const r = 6.5;
    ctx.save();
    ctx.translate(size / 2, size / 2);
    ctx.strokeStyle = "#454850";
    ctx.lineWidth = 1.4;
    ctx.lineCap = "round";
    ctx.beginPath();
    ctx.arc(0, 0, r * 0.82, 0, Math.PI * 2);
    ctx.moveTo(-r * 0.56, r * 0.56);
    ctx.lineTo(r * 0.56, -r * 0.56);
    ctx.stroke();
    ctx.restore();
    return;
  }
  iconGroovy(ctx, size, selection);
}
